const WalletControl=dynamic(()=>import('./wallet'),{ssr:false,loading:()=> <p className="muted">Loading wallet connection…</p>});
const ActionStatus=createContext({error:'',notice:'',revision:0});
const categories=['Unclassified','Food','Groceries','Transport','Home','Internet','Learning','Health','Other','Own transfer'];
