  return <form className="form-stack inset-form" onSubmit={submit}><label>Plan until<select value={kind} onChange={e=>setKind(e.target.value as 'income'|'planning')}><option value="income">Next expected income date</option><option value="planning">A selected planning end date</option></select></label><label>Local end date<input type="date" value={date} required onChange={e=>setDate(e.target.value)}/></label>{rememberedValue&&<button type="button" className="button small" disabled={demo} onClick={()=>setReserve(amount(rememberedValue,6,6).replaceAll(',',''))}>Use remembered reserve · {money(rememberedValue)} USDC</button>}<label>Virtual reserve · USDC<input inputMode="decimal" value={reserve} required onChange={e=>setReserve(e.target.value)}/></label><label>IANA timezone<input value={timezone} required onChange={e=>{setTimezone(e.target.value);setPreview(false);}}/></label>{timezone!==state.plan.timezone&&<label className="checkbox-label"><input type="checkbox" checked={preview} required onChange={e=>setPreview(e.target.checked)}/>Preview: local due dates stay as entered; chain times display in {timezone}. I confirm this change.</label>}<label className="checkbox-label"><input type="checkbox" checked={accepted} required onChange={e=>setAccepted(e.target.checked)}/>I understand the operator owns the shared memory account, its relayer processes notes, and hiding a rule is not permanent erasure. <Link href="/about">Read details</Link>.</label><label className="checkbox-label"><input type="checkbox" checked={remember} onChange={e=>setRemember(e.target.checked)}/>Also remember this reserve for future plan choices. This queues a separate write; it is usable only after confirmed recall.</label><button className="button primary" disabled={demo||busy||!accepted}>Save explicit plan</button></form>;
