  const outgoing=state.movements.filter(m=>m.coinType===USDC_TYPE&&integer(m.delta)<0n&&m.status==='success'&&m.operation==='simple_transfer'&&!state.annotations.find(a=>a.movementId===m.id)?.ownTransfer);
